INSERT INTO company_profiles (org_id, display_name_en, display_name_ar, slug, tagline_en, description_en, industry, company_size, headquarters, website, benefits, is_verified) VALUES
  ('a0000000-0000-0000-0000-000000000001', 'TechVista Solutions', 'تك فيستا سوليوشنز', 'techvista', 'Building the future of enterprise software', 'TechVista Solutions is a leading Saudi technology company specializing in enterprise software solutions, cloud infrastructure, and AI-powered products. Founded in 2018, we serve clients across government and private sectors.', 'Technology', '51-200', 'Riyadh', 'https://techvista.sa', ARRAY['Health insurance', 'Annual bonus', 'Remote work options', 'Learning budget', 'Gym membership'], true),
  ('a0000000-0000-0000-0000-000000000002', 'BuildSaudi Construction', 'بيلد السعودية للمقاولات', 'buildsaudi', 'Building Saudi Arabia''s megaprojects', 'BuildSaudi is one of the Kingdom''s premier construction companies, delivering megaprojects across residential, commercial, and infrastructure sectors. We are a key partner in Vision 2030 initiatives.', 'Construction', '201-500', 'Jeddah', 'https://buildsaudi.sa', ARRAY['Housing allowance', 'Transportation', 'Annual leave 30 days', 'End of service benefits'], true),
  ('a0000000-0000-0000-0000-000000000003', 'HealthFirst KSA', 'هيلث فيرست', 'healthfirst', 'Healthcare excellence for Saudi Arabia', 'HealthFirst operates a network of hospitals and clinics across the Eastern Province. We are committed to providing world-class healthcare services with the latest medical technologies.', 'Healthcare', '500+', 'Dammam', 'https://healthfirst.sa', ARRAY['Medical insurance (family)', 'Continuing education', 'Relocation support', 'Housing'], true),
  ('a0000000-0000-0000-0000-000000000004', 'NEOM Digital', 'نيوم ديجيتال', 'neom-digital', 'Designing the city of the future', 'NEOM Digital is the technology arm of NEOM, developing smart city solutions, IoT infrastructure, and digital services for the most ambitious urban project in history.', 'Technology', '201-500', 'NEOM', 'https://neom.com', ARRAY['Competitive salary', 'Housing in NEOM', 'World-class facilities', 'International team', 'Career growth'], true),
  ('a0000000-0000-0000-0000-000000000005', 'Al Rajhi Ventures', 'الراجحي فينتشرز', 'alrajhi-ventures', 'Investing in Saudi Arabia''s future', 'Al Rajhi Ventures is the venture capital and investment arm focused on fintech, proptech, and emerging technologies in the MENA region.', 'Finance', '51-200', 'Riyadh', 'https://alrajhi-ventures.sa', ARRAY['Stock options', 'Annual bonus', 'Flexible hours', 'Premium insurance'], true);

-- ===== JOB POSTINGS =====

INSERT INTO job_postings (id, org_id, slug, title_en, title_ar, city, employment_type, min_experience_years, education_level, salary_visible, salary_min, salary_max, description_en, requirements_en, status, published_at, created_by) VALUES
  -- TechVista (4 jobs)
  ('b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'senior-software-engineer-riyadh', 'Senior Software Engineer', 'مهندس برمجيات أول', 'Riyadh', 'full_time', 5, 'bachelors', true, 18000, 28000, 'We are looking for a Senior Software Engineer to join our core platform team. You will design and build scalable microservices, mentor junior engineers, and drive technical architecture decisions.', 'Requirements:\n- 5+ years of experience in software development\n- Strong proficiency in TypeScript, Node.js, and React\n- Experience with PostgreSQL and Redis\n- Familiarity with cloud platforms (AWS/GCP)\n- Strong system design skills\n- Bachelor''s degree in Computer Science or related field', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000001', 'product-manager-riyadh', 'Product Manager', 'مدير منتجات', 'Riyadh', 'full_time', 3, 'bachelors', true, 20000, 30000, 'Join our product team to define and execute the product roadmap for our enterprise SaaS platform. You will work closely with engineering, design, and customers.', 'Requirements:\n- 3+ years in product management (B2B SaaS preferred)\n- Strong analytical and data-driven mindset\n- Excellent communication in English and Arabic\n- Experience with Agile/Scrum methodologies\n- Technical background is a plus', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000001', 'ui-ux-designer', 'UI/UX Designer', 'مصمم واجهات', 'Riyadh', 'full_time', 2, 'bachelors', true, 12000, 18000, 'Design beautiful, intuitive interfaces for our products. Work with product managers and engineers to deliver exceptional user experiences.', 'Requirements:\n- 2+ years of UI/UX design experience\n- Proficiency in Figma\n- Strong portfolio\n- Understanding of design systems\n- Arabic and English proficiency', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000001', 'devops-engineer', 'DevOps Engineer', 'مهندس DevOps', 'Riyadh', 'full_time', 3, 'bachelors', true, 16000, 24000, 'Build and maintain our CI/CD pipelines, cloud infrastructure, and monitoring systems. Ensure high availability and performance of production systems.', 'Requirements:\n- 3+ years DevOps/SRE experience\n- Kubernetes, Docker, Terraform\n- AWS or GCP certification preferred\n- Monitoring (Prometheus, Grafana)\n- Scripting (Bash, Python)', 'published', now(),  NULL),

  -- BuildSaudi (3 jobs)
  ('b0000000-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000002', 'civil-engineer-jeddah', 'Civil Engineer', 'مهندس مدني', 'Jeddah', 'full_time', 3, 'bachelors', true, 12000, 18000, 'Join our engineering team working on large-scale residential and commercial projects in Jeddah. You will oversee structural design, site supervision, and quality control.', 'Requirements:\n- Bachelor''s in Civil Engineering\n- 3+ years construction experience\n- Saudi Council of Engineers registration\n- AutoCAD and Revit proficiency\n- Project management skills', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000002', 'project-manager-construction', 'Project Manager', 'مدير مشروع', 'Jeddah', 'full_time', 7, 'bachelors', true, 22000, 35000, 'Lead major construction projects from planning through delivery. Manage budgets, timelines, contractors, and client relationships.', 'Requirements:\n- 7+ years in construction project management\n- PMP certification preferred\n- Experience with megaprojects\n- Strong stakeholder management\n- Bilingual (Arabic/English)', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000002', 'safety-officer', 'HSE Safety Officer', 'مسؤول السلامة', 'Jeddah', 'full_time', 2, 'diploma', false, NULL, NULL, 'Ensure compliance with health, safety, and environment regulations on construction sites. Conduct inspections, training, and incident investigations.', 'Requirements:\n- NEBOSH or equivalent certification\n- 2+ years HSE experience in construction\n- Knowledge of Saudi safety regulations\n- First aid certification', 'published', now(),  NULL),

  -- HealthFirst (3 jobs)
  ('b0000000-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000003', 'registered-nurse-dammam', 'Registered Nurse', 'ممرض مسجل', 'Dammam', 'full_time', 2, 'bachelors', true, 10000, 15000, 'Join our nursing team providing patient care in our flagship hospital in Dammam. Opportunity to work with the latest medical technologies.', 'Requirements:\n- Bachelor''s in Nursing (BSN)\n- Saudi nursing license (SCFHS)\n- 2+ years clinical experience\n- BLS/ACLS certification\n- English proficiency', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000003', 'hospital-administrator', 'Hospital Administrator', 'مدير مستشفى', 'Dammam', 'full_time', 10, 'masters', true, 35000, 50000, 'Oversee daily operations of our 200-bed hospital. Lead a team of 500+ staff and ensure excellence in patient care, financial performance, and regulatory compliance.', 'Requirements:\n- Master''s in Healthcare Administration or MBA\n- 10+ years in healthcare management\n- Knowledge of Saudi healthcare regulations\n- Strong leadership skills', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000003', 'medical-lab-technician', 'Medical Lab Technician', 'فني مختبرات', 'Dammam', 'full_time', 1, 'diploma', true, 8000, 12000, 'Perform diagnostic laboratory tests, maintain equipment, and ensure quality control in our clinical laboratory.', 'Requirements:\n- Diploma in Medical Laboratory Technology\n- SCFHS classification\n- 1+ years lab experience\n- Knowledge of safety protocols', 'published', now(),  NULL),

  -- NEOM Digital (5 jobs)
  ('b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000004', 'iot-engineer-neom', 'IoT Engineer', 'مهندس إنترنت الأشياء', 'NEOM', 'full_time', 4, 'bachelors', true, 22000, 35000, 'Design and implement IoT solutions for NEOM''s smart city infrastructure. Work on sensor networks, edge computing, and real-time data processing.', 'Requirements:\n- 4+ years IoT development experience\n- Embedded systems (ARM, RTOS)\n- MQTT, CoAP protocols\n- Python, C/C++\n- Cloud IoT platforms (AWS IoT, Azure IoT)', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000004', 'data-scientist-neom', 'Data Scientist', 'عالم بيانات', 'NEOM', 'full_time', 3, 'masters', true, 25000, 40000, 'Apply machine learning and data analytics to solve complex urban planning challenges. Work with vast datasets from sensors, satellites, and simulations.', 'Requirements:\n- Master''s or PhD in Data Science, ML, or related\n- 3+ years applied ML experience\n- Python, TensorFlow/PyTorch\n- Experience with large-scale data\n- Strong communication skills', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000004', 'frontend-developer-neom', 'Senior Frontend Developer', 'مطور واجهات أمامية', 'NEOM', 'remote', 4, 'bachelors', true, 20000, 30000, 'Build world-class web applications for NEOM''s digital platforms. React, TypeScript, and modern frontend architecture.', 'Requirements:\n- 4+ years frontend development\n- React, TypeScript, Next.js\n- Design system experience\n- Performance optimization\n- Accessibility (WCAG)', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000014', 'a0000000-0000-0000-0000-000000000004', 'smart-city-architect', 'Smart City Solutions Architect', 'مهندس حلول المدن الذكية', 'NEOM', 'full_time', 8, 'masters', true, 40000, 60000, 'Design the technical architecture for NEOM''s integrated smart city systems. Lead cross-functional teams delivering city-scale technology solutions.', 'Requirements:\n- 8+ years in systems architecture\n- Smart city or large-scale IoT experience\n- Multi-cloud architecture\n- Team leadership\n- Vision 2030 alignment', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000015', 'a0000000-0000-0000-0000-000000000004', 'cybersecurity-analyst-neom', 'Cybersecurity Analyst', 'محلل أمن سيبراني', 'NEOM', 'full_time', 3, 'bachelors', true, 18000, 28000, 'Protect NEOM''s digital infrastructure. Monitor threats, respond to incidents, and implement security controls across our smart city systems.', 'Requirements:\n- 3+ years in cybersecurity\n- CISSP, CEH, or equivalent\n- SIEM tools (Splunk, QRadar)\n- Incident response experience\n- Knowledge of OT/ICS security a plus', 'published', now(),  NULL),

  -- Al Rajhi Ventures (2 jobs)
  ('b0000000-0000-0000-0000-000000000016', 'a0000000-0000-0000-0000-000000000005', 'fintech-analyst', 'Fintech Investment Analyst', 'محلل استثمار التقنية المالية', 'Riyadh', 'full_time', 2, 'bachelors', true, 15000, 22000, 'Evaluate fintech investment opportunities across MENA. Conduct due diligence, financial modeling, and market research.', 'Requirements:\n- 2+ years in VC, PE, or investment banking\n- Strong financial modeling skills\n- Understanding of fintech landscape\n- MBA or CFA is a plus\n- Bilingual (Arabic/English)', 'published', now(),  NULL),
  ('b0000000-0000-0000-0000-000000000017', 'a0000000-0000-0000-0000-000000000005', 'marketing-manager-riyadh', 'Marketing Manager', 'مدير تسويق', 'Riyadh', 'full_time', 5, 'bachelors', true, 18000, 25000, 'Lead marketing strategy for our portfolio companies and brand. Digital marketing, events, and investor communications.', 'Requirements:\n- 5+ years marketing experience\n- B2B and B2C experience\n- Digital marketing expertise\n- Event management\n- Bilingual content creation', 'published', now(),  NULL);

